BIGFIVE_TEMPLATE = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Big Five · Exploratory report</title>
<style>
:root{font-family:"Segoe UI",system-ui,sans-serif;color:#25213a;background:#f5f3fa;font-synthesis:none}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 4% 8%,#e9e1ff,transparent 40%),#f7f6fc}.wrap{max-width:1020px;margin:auto;padding:30px 24px 60px}header{background:#251a3b;color:white;padding:42px max(calc((100vw - 1020px)/2),24px) 45px}header .eyebrow{text-transform:uppercase;letter-spacing:2px;font-size:11px;color:#c7adff;font-weight:700}h1{font-size:clamp(32px,5vw,54px);line-height:1.08;letter-spacing:-1.6px;margin:14px 0}header p{max-width:720px;color:#d5cce3;line-height:1.7;margin:0}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;background:#fff;border:1px solid #e8e2f1;border-radius:14px;padding:16px;margin:24px 0}.toolbar label{font-size:12px;font-weight:700;color:#726681}select,button,.button{font:inherit;font-size:13px;padding:10px 14px;border:1px solid #e4dced;border-radius:9px;background:white;color:#403753}select{flex:1;min-width:230px}.button{color:#fff;background:#7251d3;border-color:#7251d3;text-decoration:none}.panel{background:white;border:1px solid #e8e2f1;border-radius:16px;padding:25px;margin:18px 0}.kicker{color:#8b70b3;text-transform:uppercase;letter-spacing:1.8px;font-size:10px;font-weight:750;margin:0 0 8px}h2{font-size:21px;letter-spacing:-.4px;margin:0 0 12px}.intro{line-height:1.7;color:#675d76;margin:0}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:18px}.stat{background:#f4effb;border-radius:11px;padding:16px}.stat strong{display:block;font-size:23px;color:#6043a4}.stat span{font-size:11px;color:#756985}.traits{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px}.trait{border:1px solid #eee8f5;border-radius:12px;padding:16px}.trait-head{display:flex;justify-content:space-between;gap:12px;align-items:start}.trait h3{margin:0;font-size:15px}.rate{font-size:12px;color:#6849aa;font-weight:700;white-space:nowrap}progress{width:100%;height:9px;appearance:none;border:0;border-radius:12px;overflow:hidden;background:#eeeaf4;margin:13px 0 7px}progress::-webkit-progress-bar{background:#eeeaf4}progress::-webkit-progress-value{background:linear-gradient(90deg,#b795f4,#7550cc);border-radius:12px}progress::-moz-progress-bar{background:#8960d7;border-radius:12px}.trait p{font-size:12px;line-height:1.55;color:#746982;margin:4px 0}.trait .evidence{color:#514369}.callout{background:#f3effb;border-left:4px solid #9872e2;padding:15px 17px;border-radius:7px;line-height:1.7;color:#5e536f;font-size:13px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:16px}.step{padding:15px;border:1px solid #eee8f5;border-radius:11px}.step b{display:block;color:#61459d;margin-bottom:5px}.step span{font-size:12px;color:#736984;line-height:1.55;display:block}footer{padding:20px 2px;color:#887e94;font-size:11px;line-height:1.6}.empty{padding:24px;border-radius:10px;background:#faf7ff;color:#796b89;line-height:1.6}@media(max-width:680px){.traits{grid-template-columns:1fr}.steps{grid-template-columns:1fr}.stats{grid-template-columns:1fr}.wrap{padding:18px 14px 40px}header{padding:35px 20px}.panel{padding:20px}}@media print{body{background:#fff}.wrap{max-width:none;padding:0}header{padding:24px 30px}.toolbar .button,button{display:none}.toolbar{margin:12px 0;padding:8px}.panel{break-inside:avoid;box-shadow:none;margin:10px 0;padding:16px}.trait{break-inside:avoid}.traits{gap:8px}.steps{gap:8px}footer{font-size:9px}}
#analyze{cursor:pointer;background:#7251d3;color:white;border:0;border-radius:9px;padding:11px 16px;font-weight:650}#analyze:disabled{opacity:.55;cursor:wait}.ai-results{margin-top:16px}.ai-summary{grid-column:1/-1}.ai-quote{border-left:3px solid #b99be9;padding:7px 11px;background:#faf8fd;color:#584a6d;margin-top:8px;font-size:12px;line-height:1.55}.ai-signal{display:inline-block;border-radius:20px;background:#eee8fa;color:#6647a4;padding:5px 9px;font-size:10px;font-weight:700;margin:9px 0}</style></head><body><header><div class="wrap" style="padding:0"><span class="eyebrow">Report · Instagram text analysis</span><h1>Big Five<br>exploratory language signals</h1><p>A descriptive look at the vocabulary in the account’s captions. It presents text patterns; it does not determine what a person is like.</p></div></header><main class="wrap"><div class="toolbar"><label for="run">Account / extraction</label><select id="run"></select><a class="button" href="dashboard.html">Back to dashboard</a><button id="print" type="button">Print / Save PDF</button></div><section class="panel"><p class="kicker">01 · The sample</p><h2 id="profile">Account</h2><p class="intro">The Big Five is a five-dimension personality framework. This report uses it only to organize lexical signals; results describe the captured text, not its author.</p><div id="stats" class="stats"></div></section><section class="panel"><p class="kicker">02 · What appears in the text</p><h2>Vocabulary frequency by dimension</h2><p class="intro">The value shows matches from an exploratory vocabulary list per 100 corpus words. The bar is visually capped at 10 matches per 100 words.</p><div id="results" class="traits"></div><p id="note" class="callout"></p></section><section class="panel"><p class="kicker">03 · Qualitative analysis with Gemini</p><h2>AI-assisted text review</h2><p class="intro">When you click the button, captions from this extraction are sent to Google Gemini over the internet. The username is not sent. Use this report to explore the text, not to evaluate a person.</p><button id="analyze" type="button">Analyze captions with Gemini</button><p id="ai-status" class="callout" role="status">AI analysis is optional and only runs when you click the button.</p><div id="ai-results" class="traits"></div></section><section class="panel"><p class="kicker">04 · Presentation guide</p><h2>How to read this report</h2><div class="steps"><div class="step"><b>What we did</b><span>We reviewed available captions and counted matches to Spanish word lists associated with each dimension.</span></div><div class="step"><b>What the bars show</b><span>Relative frequency in this sample. A higher value only means more words from that list appeared; it is not a personality score.</span></div><div class="step"><b>What we cannot conclude</b><span>Intentions, behavior outside Instagram, or a psychological profile. Topic, style, irony, language, and sample size affect vocabulary.</span></div></div></section><section class="panel"><p class="kicker">Interpretation limits</p><p class="callout">This heuristic analysis is not validated as a psychometric instrument. It is not a Big Five test, diagnosis, employment screening tool, or person evaluation. Comments written by others are not analyzed. Use it to describe the corpus and its visible words, not to make decisions about someone.</p></section><footer>Source: captions saved in the selected local extraction. Minimum display sample: 3 text captions and 50 words. Lexical frequencies are calculated locally. Gemini analyzes captions only when you click the button and the local server is running.</footer></main>
<script>
'use strict';
const runs=/* DATA */[];
const BIG_FIVE=[
 {name:'Openness to experience',desc:'Interest in ideas, creativity, learning, culture, and new experiences.',terms:['arte','artista','creatividad','crear','curiosidad','curioso','aprender','explorar','descubrir','imaginar','cultura','libro','leer','música','viaje','viajar','ideas','naturaleza']},
 {name:'Conscientiousness',desc:'Vocabulary about goals, organization, persistence, and work.',terms:['meta','metas','disciplina','trabajo','esfuerzo','lograr','organizar','constancia','proyecto','cumplir','hábito','hábitos','planificar','objetivo','objetivos','dedicación','responsabilidad','preparar']},
 {name:'Extraversion',desc:'Language related to sociability, energy, shared activities, and conversation.',terms:['amigos','amistad','fiesta','juntos','compartir','conocer','celebrar','energía','hablar','equipo','gente','social','reunión','salir','conversar','comunidad','diversión']},
 {name:'Agreeableness',desc:'Words related to support, care, gratitude, and consideration for others.',terms:['gracias','amor','ayudar','apoyo','cuidar','familia','respeto','empatía','amable','amistad','agradecido','agradecida','cariño','compasión','equipo','juntos','solidaridad']},
 {name:'Neuroticism · emotional vocabulary',desc:'Terms related to distress or worry. Their presence cannot establish emotional stability.',terms:['miedo','ansiedad','preocupación','preocupar','difícil','estrés','triste','tristeza','frustración','dolor','agotado','agotada','incertidumbre','nervioso','nerviosa','angustia','temor']}
];
const $=id=>document.getElementById(id);
function node(tag,text,className){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(className)el.className=className;return el;}
function normalizedWord(word){return word.normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
function render(){const run=runs[$('run').value],profile=run?.profile||{},posts=run?.captions||[];const captions=posts.filter(text=>typeof text==='string'&&text.trim());const tokens=captions.join(' ').toLocaleLowerCase('en-US').normalize('NFC').match(/[\p{L}\p{M}]+/gu)||[];const words=tokens.map(normalizedWord);$('profile').textContent=profile.username?'@'+profile.username:'Account name unavailable';$('stats').replaceChildren();for(const [value,label] of [[captions.length,'text captions'],[tokens.length,'words analyzed'],[run?.name||'—','extraction date / ID']]){const box=node('div',undefined,'stat');box.append(node('strong',String(value)),node('span',label));$('stats').append(box);}const root=$('results');root.replaceChildren();
 if(tokens.length<50||captions.length<3){root.append(node('div',`Insufficient sample: at least 50 words across 3 captions are required. This extraction contains ${tokens.length} words across ${captions.length} text captions.`,'empty'));$('note').textContent='Frequencies are hidden to avoid presenting a small sample as a pattern.';return;}
 for(const trait of BIG_FIVE){const terms=new Map();for(const term of trait.terms)terms.set(normalizedWord(term),term);let hits=0;const examples=[];for(const [word,display] of terms){const count=words.filter(item=>item===word).length;if(count){hits+=count;examples.push(display);}}const rate=hits/tokens.length*100,card=node('article',undefined,'trait'),head=node('div',undefined,'trait-head');head.append(node('h3',trait.name),node('span',rate.toFixed(1)+' / 100 words','rate'));const bar=node('progress');bar.max=10;bar.value=Math.min(rate,10);bar.setAttribute('aria-label',trait.name+': '+rate.toFixed(1)+' matches per 100 words');card.append(head,bar,node('p',trait.desc),node('p',hits?`${hits} matches. Observed words: ${examples.slice(0,6).join(', ')}${examples.length>6?'…':''}`:'No matches from this word list.','evidence'));root.append(card);}
 $('note').textContent=`Reading: across ${tokens.length} words in ${captions.length} captions, these bars summarize matches to a predefined vocabulary. Frequency does not indicate trait intensity or enable comparisons between people.`;}
async function runGemini(){const button=$('analyze'),status=$('ai-status');if(location.protocol==='file:'){status.textContent='Open the dashboard through the local server to enable Gemini. See README.md.';return;}const captions=(runs[$('run').value]?.captions||[]).filter(text=>typeof text==='string'&&text.trim());const words=captions.join(' ').match(/[\p{L}\p{M}]+/gu)||[];if(captions.length<3||words.length<50){status.textContent=`Insufficient sample: 3 captions and 50 words are required. Found ${captions.length} captions and ${words.length} words.`;return;}button.disabled=true;status.textContent='Gemini is analyzing the captions…';$('ai-results').replaceChildren();try{const response=await fetch('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({captions})});const result=await response.json();if(!response.ok)throw new Error(result.error||'The analysis could not be completed.');renderGeminiResult(result);status.textContent=`Analysis generated by ${result.model||'Gemini'}. Observations refer to the text and are not Big Five scores.`;}catch(error){status.textContent=error.message||'Could not connect to the local server.';}finally{button.disabled=false;}}
function renderGeminiResult(result){const root=$('ai-results');root.replaceChildren();const summary=document.createElement('article');summary.className='trait ai-summary';summary.append(node('h3','Corpus summary'),node('p',result.summary||'No summary.'));root.append(summary);for(const item of result.traits||[]){const card=document.createElement('article');card.className='trait';card.append(node('h3',item.name));card.append(node('span',item.signal,'ai-signal'),node('p',item.analysis||''));for(const quote of item.evidence||[])card.append(node('blockquote','“'+quote+'”','ai-quote'));root.append(card);}}
 runs.forEach((run,index)=>{const option=node('option',(run.profile?.username?'@'+run.profile.username:'Account')+' · '+run.name);option.value=index;$('run').append(option);});if(!runs.length){$('run').append(node('option','No extractions available'));$('results').append(node('div','No saved data found. Run the scraper and rebuild the dashboard.','empty'));$('profile').textContent='No data';}else render();$('run').onchange=render;$('print').onclick=()=>window.print();$('analyze').onclick=runGemini;
</script></body></html>
"""
def generate_dashboard(results=None, output=BASE / 'dashboard.html'):
    roots = [results] if results is not None else [BASE / 'results', BASE / 'results']
    runs = []
    for root in roots:
        for file in root.glob('*/data.json'):
            try:
                data = json.loads(file.read_text(encoding='utf-8'))
                if not isinstance(data, dict) or not isinstance(data.get('posts'), list):
                    continue
                for post in data['posts']:
                    post.pop('preview', None)
                    if post.get('screenshot'):
                        image = (file.parent / post['screenshot']).resolve()
                        if image.is_relative_to(file.parent.resolve()) and image.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'} and image.is_file():
                            mime = {'.png': 'png', '.webp': 'webp'}.get(image.suffix.lower(), 'jpeg')
                            post['preview'] = f'data:image/{mime};base64,' + base64.b64encode(image.read_bytes()).decode('ascii')
                runs.append({'name': file.parent.name, 'data': data})
            except (OSError, ValueError, TypeError):
                continue
    runs.sort(key=lambda run: run['name'], reverse=True)
    report_runs = [{'name': run['name'], 'profile': {'username': (run['data'].get('profile') or {}).get('username')}, 'captions': [post.get('caption') for post in run['data'].get('posts', []) if isinstance(post, dict) and post.get('caption')]} for run in runs]
    report_content = json.dumps(report_runs, ensure_ascii=True).replace('<', '\\u003c')
    report_path = output.with_name('bigfive.html')
    report_path.write_text(BIGFIVE_TEMPLATE.replace('/* DATA */[]', report_content), encoding='utf-8')
    benford_runs = [{'name': run['name'], 'data': {key: run['data'].get(key) for key in ('profile', 'benford_minimum', 'followers')}} for run in runs]
    benford_content = json.dumps(benford_runs, ensure_ascii=True).replace('<', '\\u003c')
    output.with_name('benford.html').write_text(BENFORD_TEMPLATE.replace('/* DATA */[]', benford_content), encoding='utf-8')
    content = json.dumps(runs, ensure_ascii=True).replace('<', '\\u003c')
    output.write_text(TEMPLATE.replace('/* DATA */[]', content), encoding='utf-8')
    return output


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--results', type=Path, help='Directory containing extraction runs.')
    parser.add_argument('--output', type=Path, default=BASE / 'dashboard.html')
    args = parser.parse_args()
    print(generate_dashboard(args.results, args.output))
